const store = $getWorkflowStaticData('global');

if (!store.users) store.users = {};
if (!store.jobs) store.jobs = [];

const m = $json.message ?? {};
const text = (m.text ?? '').trim();

const chatId = m.chat?.id;
const telegramId = String(m.from?.id ?? '');

if (!chatId || !telegramId) {
  return [];
}

if (!store.users[telegramId]) {
  store.users[telegramId] = {
    telegram_id: telegramId,
    chat_id: chatId,
    username: m.from?.username ?? '',
    first_name: m.from?.first_name ?? '',
    language: 'ar-SA',
    voice: 'ar-SA-HamedNeural',
    video_aspect: '9:16',
    awaiting: null,
    created_at: new Date().toISOString()
  };
}

const user = store.users[telegramId];

user.chat_id = chatId;
user.username = m.from?.username ?? user.username ?? '';
user.first_name = m.from?.first_name ?? user.first_name ?? '';
user.last_seen_at = new Date().toISOString();

let command = '';
if (text.startsWith('/')) {
  command = text.split(/\s+/)[0].split('@')[0].toLowerCase();
}

let route = 'reply';
let reply = '';
let videoSubject = '';

if (command === '/start') {

  user.awaiting = null;

  reply =
`🎬 Pingoo Video جاهز

/video إنشاء فيديو
/status حالة الطلب
/history السجل
/settings الإعدادات
/cancel إلغاء الطلب`;

} else if (command === '/video') {

  videoSubject = text
    .replace(/^\/video(?:@\w+)?/i, '')
    .trim();

  if (!videoSubject) {
    user.awaiting = 'video_topic';

    reply =
`🎬 أرسل الآن موضوع الفيديو.

مثال:
أفضل 5 أماكن سياحية في السعودية`;

  } else {
    user.awaiting = null;
    route = 'video';

    reply =
`⏳ تم استلام الموضوع:
${videoSubject}

جاري إنشاء المهمة...`;
  }

} else if (!command && user.awaiting === 'video_topic' && text) {

  videoSubject = text;
  user.awaiting = null;
  route = 'video';

  reply =
`⏳ تم استلام الموضوع:
${videoSubject}

جاري إنشاء المهمة...`;

} else if (command === '/status') {

  const job = store.jobs.find(
    j => String(j.telegram_id) === telegramId
  );

  if (!job) {
    reply = '📊 لا توجد لديك مهمة محفوظة حتى الآن.';
  } else {
    reply =
`📊 آخر مهمة

الموضوع: ${job.topic}
Task ID: ${job.task_id}
الحالة: ${job.status}
التقدم: ${job.progress ?? 0}%`;
  }

} else if (command === '/history') {

  const jobs = store.jobs
    .filter(j => String(j.telegram_id) === telegramId)
    .slice(0,5);

  if (!jobs.length) {
    reply = '📚 السجل فارغ.';
  } else {
    reply =
      '📚 آخر المهام\n\n' +
      jobs.map((j,i) =>
        `${i+1}. ${j.topic}\n${j.task_id}\n${j.status}`
      ).join('\n\n');
  }

} else if (command === '/settings') {

  reply =
`⚙️ الإعدادات الحالية

اللغة: ${user.language}
الصوت: ${user.voice}
المقاس: ${user.video_aspect}`;

} else if (command === '/cancel') {

  user.awaiting = null;

  reply =
`❌ تم إلغاء أي طلب إدخال غير مكتمل.

إلغاء مهمة معالجة فعلية سيتم ربطه في مرحلة /cancel.`;

} else {

  reply =
`الأمر غير معروف.

استخدم /start لعرض الأوامر.`;
}

return [{
  json: {
    chat_id: chatId,
    telegram_id: telegramId,
    username: user.username,
    command,
    route,
    video_subject: videoSubject,
    video_language: user.language,
    voice_name: user.voice,
    video_aspect: user.video_aspect,
    reply
  }
}];

